tasks.solution:
#include <stdio.h>

// 호출 횟수를 세어 돌려줘요.
int bump(void) {
    // 이 선언에 static을 붙여 호출 사이에도 calls가 남게 하세요.
    // static 지역 변수는 프로그램이 끝날 때까지 남고, 처음 한 번만 0으로 준비돼요.
    static int calls = 0;
    calls = calls + 1;
    return calls;
}

int main(void) {
    int times = 2;
    for (int i = 0; i < times; i++) {
        printf("%d\n", bump());
    }
    return 0;
}

